using namespace boost::posix_time;

TEST_CASE("date only specification of time",
          "[92fbe71c-ea52-4fac-bd77-be38023cacf7]") {
    const ptime actual =
        gigasecond::advance(time_from_string("2011-04-25 00:00:00"));

